insert into public.species_moves (species_id, move_id, min_rank)
select s.id, m.id, incoming.min_rank::public.pokerole_rank
from incoming
join public.species s on s.name = incoming.species_name
join public.moves m on m.name = incoming.move_name
on conflict (species_id, move_id) do update set min_rank = excluded.min_rank;

